using System.Text.Json;
using System.Text.Json.Serialization;
using Angadi.Domain.Common;
using Angadi.Domain.Items;

namespace Angadi.Infrastructure.Seed;

/// <summary>
/// FR-04 sample items, embedded from Seed/kirana.json (80) and Seed/pharmacy.json (40).
/// Generated by tools/generate_seed.py, which also guarantees no alias collides between items.
/// </summary>
public static class SeedCatalog
{
    public sealed record SeedItem(Item Item, Qty OpeningStock);

    public static IReadOnlyList<SeedItem> Kirana() => Load("kirana.json");
    // v2-stock: pharmacy items start with "Track batch & expiry" on (the owner can switch it off per item).
    public static IReadOnlyList<SeedItem> Pharmacy() => Load("pharmacy.json", tracksBatches: true);

    private static readonly JsonSerializerOptions Json = new()
    {
        PropertyNameCaseInsensitive = true,
        Converters = { new JsonStringEnumConverter() },
    };

    private static IReadOnlyList<SeedItem> Load(string file, bool tracksBatches = false)
    {
        using var stream = typeof(SeedCatalog).Assembly.GetManifestResourceStream($"Angadi.Seed.{file}")
            ?? throw new InvalidOperationException($"Missing seed resource {file}");
        var doc = JsonSerializer.Deserialize<SeedFile>(stream, Json) ?? throw new InvalidOperationException($"Empty seed {file}");

        return doc.Items.Select(r => new SeedItem(new Item
        {
            TeluguName = r.Te,
            EnglishName = r.En,
            Aliases = [.. r.Aliases],
            Category = r.Category,
            Unit = r.Unit,
            Price = new Paise(r.PricePaise),
            GstSlab = (GstSlab)r.GstBasisPoints,
            LowStockThreshold = new Qty(r.LowStockMilli),
            IsQuickSale = r.QuickSale,
            TracksBatches = tracksBatches,
        }, new Qty(r.OpeningStockMilli))).ToList();
    }

    private sealed record SeedFile(List<SeedRow> Items);

    private sealed record SeedRow(
        string Te, string En, List<string> Aliases, string Category, Unit Unit,
        long PricePaise, int GstBasisPoints, long OpeningStockMilli, long LowStockMilli, bool QuickSale);
}
